-- Owner-only production community. No preview/test rows or roles are imported.
begin;
set local lock_timeout='5s';
select pg_advisory_xact_lock(926102829);
create schema if not exists mirpanel_community;
revoke all on schema mirpanel_community from public,anon,authenticated;
set local search_path=mirpanel_community,public;
create table if not exists release_manifest(object_name text primary key,rows_before bigint not null,captured_at timestamptz not null default clock_timestamp());
insert into release_manifest select 'public.payment_orders',count(*),clock_timestamp() from public.payment_orders on conflict do nothing;
create table if not exists "user" (id text primary key,name text not null,email text not null unique,"emailVerified" boolean not null,image text,"createdAt" timestamptz not null default CURRENT_TIMESTAMP,"updatedAt" timestamptz not null default CURRENT_TIMESTAMP);
create table if not exists session(id text primary key,"expiresAt" timestamptz not null,token text not null unique,"createdAt" timestamptz not null default CURRENT_TIMESTAMP,"updatedAt" timestamptz not null,"ipAddress" text,"userAgent" text,"userId" text not null references "user"(id) on delete cascade);
create index if not exists community_session_user on session("userId");
create table if not exists account(id text primary key,"accountId" text not null,"providerId" text not null,"userId" text not null references "user"(id) on delete cascade,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz not null default CURRENT_TIMESTAMP,"updatedAt" timestamptz not null);
create unique index if not exists community_provider_identity on account("providerId","accountId");
create table if not exists verification(id text primary key,identifier text not null,value text not null,"expiresAt" timestamptz not null,"createdAt" timestamptz not null default CURRENT_TIMESTAMP,"updatedAt" timestamptz not null default CURRENT_TIMESTAMP);
create table if not exists community_config(id boolean primary key default true check(id),enabled boolean not null default true,version integer not null default 1,tiers jsonb not null);
insert into community_config(id,tiers) values(true,'[{"id":"standard","name":"Standart","cents":0},{"id":"bronze","name":"Bürünc","cents":3000},{"id":"silver","name":"Gümüş","cents":10000},{"id":"gold","name":"Qızıl","cents":25000},{"id":"vip","name":"VIP","cents":50000}]') on conflict do nothing;
create table if not exists community_profiles(user_id text primary key references "user"(id),display_name text not null,avatar integer not null default 0 check(avatar between 0 and 7),blocked boolean not null default false,muted_until timestamptz,muted_permanent boolean not null default false,ban_until timestamptz);
create table if not exists community_group_roles(user_id text primary key references "user"(id),role text not null check(role in ('owner','moderator')),created_at timestamptz not null default clock_timestamp());
create unique index if not exists community_single_owner on community_group_roles(role) where role='owner';
create table if not exists owner_identity(id boolean primary key default true check(id),user_id text not null unique references "user"(id),google_subject text not null unique,verified_email text not null,created_at timestamptz not null default clock_timestamp());
create table if not exists community_messages(id bigserial primary key,user_id text not null references "user"(id),client_id uuid not null,body text not null check(length(body) between 1 and 2000),hidden boolean not null default false,created_at timestamptz not null default clock_timestamp(),unique(user_id,client_id));
create table if not exists community_reads(reader_hash text primary key,last_id bigint not null default 0);
create table if not exists community_audit(id bigserial primary key,actor_id text not null references "user"(id),action text not null,target_id text not null,reason text not null,details jsonb not null default '{}',created_at timestamptz not null default clock_timestamp());
create table if not exists community_group_settings(id boolean primary key default true check(id),muted boolean not null default false,rules text not null default '',slow_seconds integer not null default 0 check(slow_seconds between 0 and 3600),pinned_message_id bigint references community_messages(id),version integer not null default 1,enabled boolean not null default true);
insert into community_group_settings(id) values(true) on conflict do nothing;
create table if not exists community_reports(id bigserial primary key,message_id bigint not null references community_messages(id),reporter_id text not null references "user"(id),reason text not null,status text not null default 'open',created_at timestamptz not null default clock_timestamp(),resolved_by text references "user"(id),resolved_at timestamptz,unique(message_id,reporter_id));
create table if not exists community_moderation_requests(actor_id text not null references "user"(id),request_id uuid not null,payload_hash text not null,result jsonb not null,created_at timestamptz not null default clock_timestamp(),primary key(actor_id,request_id));
create table if not exists community_order_owners(order_id uuid primary key references public.payment_orders(id),user_id text not null references "user"(id),linked_at timestamptz not null default clock_timestamp());
create table if not exists community_refunds(order_id uuid primary key references public.payment_orders(id),cents integer not null check(cents>=0));
create or replace function protect_owner_profile() returns trigger language plpgsql set search_path=mirpanel_community,pg_catalog as $$begin if exists(select 1 from community_group_roles where user_id=new.user_id and role='owner') and (new.blocked or new.muted_permanent or new.muted_until>clock_timestamp()) then raise exception 'OWNER_PROTECTED';end if;return new;end$$;
create or replace function protect_owner_role() returns trigger language plpgsql as $$begin if old.role='owner' then raise exception 'OWNER_ROLE_PROTECTED';end if;return old;end$$;
drop trigger if exists owner_profile_guard on community_profiles;
create trigger owner_profile_guard before update on community_profiles for each row execute function protect_owner_profile();
drop trigger if exists owner_role_guard on community_group_roles;
create trigger owner_role_guard before update or delete on community_group_roles for each row execute function protect_owner_role();
do $$declare t text;begin for t in select tablename from pg_tables where schemaname='mirpanel_community' loop execute format('alter table mirpanel_community.%I enable row level security',t);execute format('revoke all on mirpanel_community.%I from public,anon,authenticated',t);end loop;end$$;
revoke all on all sequences in schema mirpanel_community from public,anon,authenticated;
revoke all on all functions in schema mirpanel_community from public,anon,authenticated;
commit;
